    static PICKLE_LOADS: Cell<P> = const { Cell::new(std::ptr::null_mut()) };
    static PICKLE_FNS: RefCell<HashMap<usize, V>> = RefCell::new(HashMap::new());
}
unsafe fn pyd_note_pickle(p: P, n: &str) {
    if n == "dumps" || n == "loads" {
        (pyd_api().IncRef)(p);
        if n == "dumps" {
            PICKLE_DUMPS.with(|c| c.set(p));
        } else {
            PICKLE_LOADS.with(|c| c.set(p));
        }
    }
}
fn pickle_key(v: &V) -> Option<usize> {
    match v {
        V::Func(f) => Some(Rc::as_ptr(f) as usize),
        V::Bound(b) => Some(Rc::as_ptr(b) as usize),
        _ => None,
    }
}
fn pyd_pickle_dumps(args: &Args) -> R {
    let dumps = PICKLE_DUMPS.with(|c| c.get());
    let fallback = |args: &Args| unsafe { pyd_call(dumps, &[], args, true) };
    // pickle.dumps(obj[, protocol]); keywords go to CPython, whose error is its own.
    let obj = args.p.first();
    let proto = args.p.get(1).cloned().unwrap_or(V::None);
    let Some(obj) = obj else {
        return fallback(args);
    };
    let proto_ok = matches!(proto, V::None | V::Bool(_)) || matches!(&proto, V::Int(i) if (0..=5).contains(i));
    if !args.k.is_empty() || args.p.len() > 2 || !proto_ok {
        return fallback(args);
    }
    let Some(id) = pickle_key(obj) else {
        return fallback(args);
    };
    PICKLE_FNS.with(|m| m.borrow_mut().insert(id, obj.clone()));
    Ok(bytesv(format!("BVPF{id}\n").into_bytes()))
}
fn pyd_pickle_loads(args: &Args) -> R {
    let loads = PICKLE_LOADS.with(|c| c.get());
    let fallback = |args: &Args| unsafe { pyd_call(loads, &[], args, true) };
    let Some(data) = (args.p.len() == 1 && args.k.is_empty()).then(|| bytes_of(&args.p[0])).flatten() else {
        return fallback(args);
    };
    let Some(text) = data.strip_prefix(b"BVPF").and_then(|t| t.strip_suffix(b"\n")) else {
        return fallback(args);
    };
    let Some(id) = std::str::from_utf8(text).ok().and_then(|t| t.parse::<usize>().ok()) else {
        return fallback(args);
    };
    match PICKLE_FNS.with(|m| m.borrow().get(&id).cloned()) {
        Some(v) => Ok(v),
        None => Err(exc("PicklingError", format!("brevi: no function for pickle id {id}"))),
    }
}

// f(*pre, *args, **kw); the result copied when `deep`.
unsafe fn pyd_invoke(f: P, pre: &[V], args: &Args, deep: bool) -> R {
    if pre.is_empty() {
        let d = PICKLE_DUMPS.with(|c| c.get());
        if !d.is_null() && f == d {
            return pyd_pickle_dumps(args);
        }
        let l = PICKLE_LOADS.with(|c| c.get());
        if !l.is_null() && f == l {
            return pyd_pickle_loads(args);
        }
    }
    pyd_call(f, pre, args, deep)
}

