from functools import total_ordering

# root returns NotImplemented: it must propagate (operators raise TypeError)
@total_ordering
class N:
    def __init__(self, v): self.v = v
    def __eq__(self, other): return self.v == other.v
    def __lt__(self, other):
        if isinstance(other, N): return self.v < other.v
        return NotImplemented

for expr, fn in [("N(1) < N(2)", lambda: N(1) < N(2)),
                 ("N(2) > N(1)", lambda: N(2) > N(1)),
                 ("N(1) <= N(2)", lambda: N(1) <= N(2)),
                 ("N(2) >= N(1)", lambda: N(2) >= N(1)),
                 ("N(1) > 'x'", lambda: N(1) > 'x'),
                 ("N(1) <= 'x'", lambda: N(1) <= 'x'),
                 ("N(1) >= 'x'", lambda: N(1) >= 'x')]:
    try:
        print(expr, "->", fn())
    except TypeError as e:
        print(expr, "-> TypeError")

# non-bool results keep CPython's and/or short-circuit values
@total_ordering
class L:
    def __lt__(self, other): return [1]
    def __eq__(self, other): return "eq"
print(repr(L() <= L()), repr(L() >= L()), repr(L() > L()))

@total_ordering
class LE:
    def __le__(self, other): return []
    def __eq__(self, other): return "eq"
print(repr(LE() < LE()), repr(LE() >= LE()), repr(LE() > LE()))

